    37→type TransactionGenerator struct {
    38→	keystore string
    39→	seed     int64
    40→	started  chan struct{}
    41→	cancel   context.CancelFunc
    42→	paused   bool
    43→}
    44→
    45→func (t *TransactionGenerator) UnderlyingProcess() *os.Process {
    46→	// Transaction Generator runs under the same underlying process so
    47→	// we return an empty process object.
    48→	return &os.Process{}
    49→}
    50→
    51→func NewTransactionGenerator(keystore string, seed int64) *TransactionGenerator {
    52→	return &TransactionGenerator{keystore: keystore, seed: seed}
    53→}
    54→
    55→func (t *TransactionGenerator) Start(ctx context.Context) error {
    56→	// Wrap context with a cancel func
    57→	ctx, ccl := context.WithCancel(ctx)
    58→	t.cancel = ccl
    59→
    60→	client, err := rpc.DialHTTP(fmt.Sprintf("http://127.0.0.1:%d", e2e.TestParams.Ports.Eth1RPCPort))
    61→	if err != nil {
    62→		return err
    63→	}
    64→	defer client.Close()
    65→
    66→	seed := t.seed
    67→	newGen := rand.NewDeterministicGenerator()
    68→	if seed == 0 {
    69→		seed = newGen.Int63()
    70→		logrus.Infof("Seed for transaction generator is: %d", seed)
    71→	}
    72→	// Set seed so that all transactions can be
    73→	// deterministically generated.
    74→	mathRand.Seed(seed)
    75→
    76→	keystoreBytes, err := os.ReadFile(t.keystore) // #nosec G304
    77→	if err != nil {
    78→		return err
    79→	}
    80→	mineKey, err := keystore.DecryptKey(keystoreBytes, KeystorePassword)
    81→	if err != nil {
    82→		return err
    83→	}
    84→	newKey := keystore.NewKeyForDirectICAP(newGen)
    85→	if err := fundAccount(client, mineKey, newKey); err != nil {
    86→		return err
    87→	}
    88→	fundedAccount = newKey
    89→	rnd := make([]byte, 10000)
    90→	_, err = mathRand.Read(rnd) // #nosec G404
    91→	if err != nil {
    92→		return err
    93→	}
    94→	f := filler.NewFiller(rnd)
    95→	// Broadcast Transactions every slot
    96→	txPeriod := time.Duration(params.BeaconConfig().SecondsPerSlot) * time.Second
    97→	ticker := time.NewTicker(txPeriod)
    98→	gasPrice := big.NewInt(1e11)
    99→	for {
   100→		select {
   101→		case <-ctx.Done():
   102→			return nil
   103→		case <-ticker.C:
   104→			if t.paused {
   105→				continue
   106→			}
   107→			backend := ethclient.NewClient(client)
   108→			err = SendTransaction(client, mineKey.PrivateKey, f, gasPrice, mineKey.Address.String(), txCount, backend, false)
   109→			if err != nil {
   110→				return err
   111→			}
   112→			backend.Close()
   113→		}
   114→	}
   115→}
   116→
   117→// Started checks whether beacon node set is started and all nodes are ready to be queried.
   118→func (s *TransactionGenerator) Started() <-chan struct{} {
   119→	return s.started
   120→}
   121→
   122→func SendTransaction(client *rpc.Client, key *ecdsa.PrivateKey, f *filler.Filler, gasPrice *big.Int, addr string, N uint64, backend *ethclient.Client, al bool) error {
   123→	sender := common.HexToAddress(addr)
   124→	nonce, err := backend.PendingNonceAt(context.Background(), fundedAccount.Address)
   125→	if err != nil {
   126→		return err
   127→	}
   128→	chainid, err := backend.ChainID(context.Background())
   129→	if err != nil {
   130→		return err
   131→	}
   132→	expectedPrice, err := backend.SuggestGasPrice(context.Background())
   133→	if err != nil {
   134→		return err
   135→	}
   136→	if expectedPrice.Cmp(gasPrice) > 0 {
   137→		gasPrice = expectedPrice
   138→	}
   139→	g, _ := errgroup.WithContext(context.Background())
   140→	txs := make([]*types.Transaction, 10)
   141→	for i := uint64(0); i < 10; i++ {
   142→		index := i
   143→		g.Go(func() error {
   144→			tx, err := RandomBlobTx(client, f, fundedAccount.Address, nonce+index, gasPrice, chainid, al)
   145→			if err != nil {
   146→				logrus.WithError(err).Error("Could not create blob tx")
   147→				// In the event the transaction constructed is not valid, we continue with the routine
   148→				// rather than complete stop it.
   149→				//nolint:nilerr
   150→				return nil
   151→			}
   152→			signedTx, err := types.SignTx(tx, types.NewCancunSigner(chainid), fundedAccount.PrivateKey)
   153→			if err != nil {
   154→				logrus.WithError(err).Error("Could not sign blob tx")
   155→				// We continue on in the event there is a reason we can't sign this
   156→				// transaction(unlikely).
   157→				//nolint:nilerr
   158→				return nil
   159→			}
   160→			txs[index] = signedTx
   161→			return nil
   162→		})
   163→	}
   164→
   165→	if err := g.Wait(); err != nil {
   166→		return err
   167→	}
   168→	for _, tx := range txs {
   169→		if tx == nil {
   170→			continue
   171→		}
   172→		err = backend.SendTransaction(context.Background(), tx)
   173→		if err != nil {
   174→			// Do nothing
   175→			continue
   176→		}
   177→	}
   178→
   179→	nonce, err = backend.PendingNonceAt(context.Background(), sender)
   180→	if err != nil {
   181→		return err
   182→	}
   183→
   184→	txs = make([]*types.Transaction, N)
   185→	for i := uint64(0); i < N; i++ {
   186→		index := i
   187→		g.Go(func() error {
   188→			tx, err := txfuzz.RandomValidTx(client, f, sender, nonce+index, gasPrice, chainid, al)
   189→			if err != nil {
   190→				// In the event the transaction constructed is not valid, we continue with the routine
   191→				// rather than complete stop it.
   192→				//nolint:nilerr
   193→				return nil
   194→			}
   195→			signedTx, err := types.SignTx(tx, types.NewLondonSigner(chainid), key)
   196→			if err != nil {
   197→				// We continue on in the event there is a reason we can't sign this
   198→				// transaction(unlikely).
   199→				//nolint:nilerr
   200→				return nil
   201→			}
   202→			txs[index] = signedTx
   203→			return nil
   204→		})
   205→	}
   206→	if err := g.Wait(); err != nil {
   207→		return err
   208→	}
   209→	for _, tx := range txs {
   210→		if tx == nil {
   211→			continue
   212→		}
   213→		err = backend.SendTransaction(context.Background(), tx)
   214→		if err != nil {
   215→			// Do nothing
   216→			continue
   217→		}
   218→	}
   219→	return nil
   220→}
