    34→// computeDeposits uses the deterministic validator generator to generate deposits for `nvals` (number of validators).
    35→// To control which validators should receive deposits, so that we can generate deposits at different stages of e2e,
    36→// the `offset` parameter skips the first N validators in the deterministic list.
    37→// In order to test the requirement that our deposit follower is able to handle multiple partial deposits,
    38→// the `partial` flag specifies that half of the deposits should be broken up into 2 transactions.
    39→func computeDeposits(offset, nvals int, partial bool) ([]*eth.Deposit, error) {
    40→	balances := make([]uint64, offset+nvals)
    41→	partialIndex := len(balances) // set beyond loop invariant so by default nothing gets partial
    42→	if partial {
    43→		// Validators in this range will get 2 half (MAX_EFFECTIVE_BALANCE/2) deposits.
    44→		// Upper half of the range of desired validator indices is used because these can be easily
    45→		// duplicated with a slice from this offset to the end.
    46→		partialIndex = offset + nvals/2
    47→	}
    48→	// Start setting values at `offset`. Lower elements will be discarded - setting them to zero
    49→	// ensures they don't slip through and add extra deposits.
    50→	for i := offset; i < len(balances); i++ {
    51→		if i >= partialIndex {
    52→			// these deposits will be duplicated, resulting in 2 deposits summing to MAX_EFFECTIVE_BALANCE
    53→			balances[i] = params.BeaconConfig().MaxEffectiveBalance / 2
    54→		} else {
    55→			balances[i] = params.BeaconConfig().MaxEffectiveBalance
    56→		}
    57→	}
    58→	deposits, _, err := util.DepositsWithBalance(balances)
    59→	if err != nil {
    60→		return []*eth.Deposit{}, err
    61→	}
    62→
    63→	// if partial = false, these will be a no-op (partialIndex == len(deposits)),
    64→	// otherwise it will duplicate the partial deposits.
    65→	deposits = append(deposits[offset:], deposits[partialIndex:]...)
    66→
    67→	return deposits, nil
    68→}
