   113→// Balances sums, by validator, all deposit amounts that were sent as part of the given batch.
   114→// This can be used in e2e evaluators to check that the results of deposit transactions are visible on chain.
   115→func (h *DepositHistory) Balances(batch types.DepositBatch) map[[48]byte]uint64 {
   116→	balances := make(map[[48]byte]uint64)
   117→	h.RLock()
   118→	defer h.RUnlock()
