    23→const executionToBLSPadding = 12
    24→
    25→// ProcessBLSToExecutionChanges processes a list of BLS Changes and validates them. However,
    26→// the method doesn't immediately verify the signatures in the changes and prefers to extract
    27→// a signature set from them at the end of the transition and then verify them via the
    28→// signature set.
    29→func ProcessBLSToExecutionChanges(
    30→	st state.BeaconState,
    31→	b interfaces.ReadOnlyBeaconBlock) (state.BeaconState, error) {
    32→	if b.Version() < version.Capella {
    33→		return st, nil
    34→	}
    35→	changes, err := b.Body().BLSToExecutionChanges()
    36→	if err != nil {
    37→		return nil, errors.Wrap(err, "could not get BLSToExecutionChanges")
    38→	}
    39→	// Return early if no changes
    40→	if len(changes) == 0 {
    41→		return st, nil
    42→	}
    43→	for _, change := range changes {
    44→		st, err = processBLSToExecutionChange(st, change)
    45→		if err != nil {
    46→			return nil, errors.Wrap(err, "could not process BLSToExecutionChange")
    47→		}
    48→	}
    49→	return st, nil
    50→}
    51→
    52→// processBLSToExecutionChange validates a SignedBLSToExecution message and
    53→// changes the validator's withdrawal address accordingly.
    54→//
    55→// Spec pseudocode definition:
    56→//
    57→// def process_bls_to_execution_change(state: BeaconState, signed_address_change: SignedBLSToExecutionChange) -> None:
    58→//
    59→//	validator = state.validators[address_change.validator_index]
    60→//
    61→//	assert validator.withdrawal_credentials[:1] == BLS_WITHDRAWAL_PREFIX
    62→//	assert validator.withdrawal_credentials[1:] == hash(address_change.from_bls_pubkey)[1:]
    63→//
    64→//	domain = get_domain(state, DOMAIN_BLS_TO_EXECUTION_CHANGE)
    65→//	signing_root = compute_signing_root(address_change, domain)
    66→//	assert bls.Verify(address_change.from_bls_pubkey, signing_root, signed_address_change.signature)
    67→//
    68→//	validator.withdrawal_credentials = (
    69→//	    ETH1_ADDRESS_WITHDRAWAL_PREFIX
    70→//	    + b'\x00' * 11
    71→//	    + address_change.to_execution_address
    72→//	)
    73→func processBLSToExecutionChange(st state.BeaconState, signed *ethpb.SignedBLSToExecutionChange) (state.BeaconState, error) {
    74→	// Checks that the message passes the validation conditions.
    75→	val, err := ValidateBLSToExecutionChange(st, signed)
    76→	if err != nil {
    77→		return nil, err
    78→	}
    79→
    80→	message := signed.Message
    81→	newCredentials := make([]byte, executionToBLSPadding)
    82→	newCredentials[0] = params.BeaconConfig().ETH1AddressWithdrawalPrefixByte
    83→	val.WithdrawalCredentials = append(newCredentials, message.ToExecutionAddress...)
    84→	err = st.UpdateValidatorAtIndex(message.ValidatorIndex, val)
    85→	return st, err
    86→}
    87→
    88→// ValidateBLSToExecutionChange validates the execution change message against the state and returns the
    89→// validator referenced by the message.
    90→func ValidateBLSToExecutionChange(st state.ReadOnlyBeaconState, signed *ethpb.SignedBLSToExecutionChange) (*ethpb.Validator, error) {
    91→	if signed == nil {
    92→		return nil, errNilSignedWithdrawalMessage
    93→	}
    94→	message := signed.Message
    95→	if message == nil {
    96→		return nil, errNilWithdrawalMessage
    97→	}
    98→
    99→	val, err := st.ValidatorAtIndex(message.ValidatorIndex)
   100→	if err != nil {
   101→		return nil, err
   102→	}
   103→	if val == nil {
   104→		return nil, errors.Wrap(errInvalidWithdrawalCredentials, "validator is nil") // This should not be possible.
   105→	}
   106→	cred := val.WithdrawalCredentials
   107→	if len(cred) < 2 || cred[0] != params.BeaconConfig().BLSWithdrawalPrefixByte {
   108→		return nil, errInvalidBLSPrefix
   109→	}
   110→
   111→	// hash the public key and verify it matches the withdrawal credentials
   112→	fromPubkey := message.FromBlsPubkey
   113→	hashFn := ssz.NewHasherFunc(hash.CustomSHA256Hasher())
   114→	digest := hashFn.Hash(fromPubkey)
   115→	if !bytes.Equal(digest[1:], cred[1:]) {
   116→		return nil, errInvalidWithdrawalCredentials
   117→	}
   118→	return val, nil
   119→}
