   592→func (p *Builder) handleHeaderRequestElectra(w http.ResponseWriter) {
   593→	b, err := p.retrievePendingBlockElectra()
   594→	if err != nil {
   595→		p.cfg.logger.WithError(err).Error("Could not retrieve pending block")
   596→		http.Error(w, err.Error(), http.StatusInternalServerError)
   597→		return
   598→	}
   599→
   600→	secKey, err := bls.RandKey()
   601→	if err != nil {
   602→		p.cfg.logger.WithError(err).Error("Could not retrieve secret key")
   603→		http.Error(w, err.Error(), http.StatusInternalServerError)
   604→		return
   605→	}
   606→	v := big.NewInt(0).SetBytes(bytesutil.ReverseByteOrder(b.Value))
   607→	// we set the payload value as twice its actual one so that it always chooses builder payloads vs local payloads
   608→	v = v.Mul(v, big.NewInt(2))
   609→	wObj, err := blocks.WrappedExecutionPayloadDeneb(b.Payload)
   610→	if err != nil {
   611→		p.cfg.logger.WithError(err).Error("Could not wrap execution payload")
   612→		http.Error(w, err.Error(), http.StatusInternalServerError)
   613→		return
   614→	}
   615→
   616→	hdr, err := blocks.PayloadToHeaderElectra(wObj)
   617→	if err != nil {
   618→		p.cfg.logger.WithError(err).Error("Could not make payload into header")
   619→		http.Error(w, err.Error(), http.StatusInternalServerError)
   620→		return
   621→	}
   622→	val := builderAPI.Uint256{Int: v}
   623→	var commitments []hexutil.Bytes
   624→	for _, c := range b.BlobsBundle.KzgCommitments {
   625→		copiedC := c
   626→		commitments = append(commitments, copiedC)
   627→	}
   628→	wrappedHdr, err := structs.ExecutionPayloadHeaderDenebFromConsensus(hdr)
   629→	if err != nil {
   630→		p.cfg.logger.WithError(err).Error("Could not make execution payload")
   631→		http.Error(w, err.Error(), http.StatusInternalServerError)
   632→		return
   633→	}
   634→	requests, err := b.GetDecodedExecutionRequests(params.BeaconConfig().ExecutionRequestLimits())
   635→	if err != nil {
   636→		p.cfg.logger.WithError(err).Error("Could not get decoded execution requests")
   637→		http.Error(w, err.Error(), http.StatusInternalServerError)
   638→		return
   639→	}
   640→	rv1 := structs.ExecutionRequestsFromConsensus(requests)
   641→
   642→	bid := &builderAPI.BuilderBidElectra{
   643→		Header:             wrappedHdr,
   644→		BlobKzgCommitments: commitments,
   645→		Value:              val,
   646→		Pubkey:             secKey.PublicKey().Marshal(),
   647→		ExecutionRequests:  rv1,
   648→	}
   649→
   650→	sszBid := &eth.BuilderBidElectra{
   651→		Header:             hdr,
   652→		BlobKzgCommitments: b.BlobsBundle.KzgCommitments,
   653→		Value:              val.SSZBytes(),
   654→		Pubkey:             secKey.PublicKey().Marshal(),
   655→		ExecutionRequests:  requests,
   656→	}
   657→	d, err := signing.ComputeDomain(params.BeaconConfig().DomainApplicationBuilder,
   658→		nil, /* fork version */
   659→		nil /* genesis val root */)
   660→	if err != nil {
   661→		p.cfg.logger.WithError(err).Error("Could not compute the domain")
   662→		http.Error(w, err.Error(), http.StatusInternalServerError)
   663→		return
   664→	}
   665→	rt, err := signing.ComputeSigningRoot(sszBid, d)
   666→	if err != nil {
   667→		p.cfg.logger.WithError(err).Error("Could not compute the signing root")
   668→		http.Error(w, err.Error(), http.StatusInternalServerError)
   669→		return
   670→	}
   671→	sig := secKey.Sign(rt[:])
   672→	hdrResp := &builderAPI.ExecHeaderResponseElectra{
   673→		Version: "electra",
   674→		Data: struct {
   675→			Signature hexutil.Bytes                 `json:"signature"`
   676→			Message   *builderAPI.BuilderBidElectra `json:"message"`
   677→		}{
   678→			Signature: sig.Marshal(),
   679→			Message:   bid,
   680→		},
   681→	}
   682→	w.WriteHeader(http.StatusOK)
   683→	err = json.NewEncoder(w).Encode(hdrResp)
   684→	if err != nil {
   685→		p.cfg.logger.WithError(err).Error("Could not encode response")
   686→		http.Error(w, err.Error(), http.StatusInternalServerError)
   687→		return
   688→	}
   689→	p.currVersion = version.Electra
   690→	p.currPayload = wObj
   691→	p.blobBundle = b.BlobsBundle
   692→}
