    92→	if err := verifyDepositDataSigningRoot(data, domain); err != nil {
    93→		// Ignore this error as in the spec pseudo code.
    94→		log.WithError(err).Debug("Skipping deposit: could not verify deposit data signature")
    95→		return false, nil
    96→	}
    97→	return true, nil
    98→}
