    52→// WrappedExecutionPayload is a constructor which wraps a protobuf execution payload into an interface.
    53→func WrappedExecutionPayload(p *enginev1.ExecutionPayload) (interfaces.ExecutionData, error) {
    54→	w := executionPayload{p: p}
    55→	if w.IsNil() {
    56→		return nil, consensus_types.ErrNilObjectWrapped
    57→	}
    58→	return w, nil
    59→}
