    25→// ProcessBLSToExecutionChanges processes a list of BLS Changes and validates them. However,
    26→// the method doesn't immediately verify the signatures in the changes and prefers to extract
    27→// a signature set from them at the end of the transition and then verify them via the
    28→// signature set.
    29→func ProcessBLSToExecutionChanges(
    30→	st state.BeaconState,
    31→	b interfaces.ReadOnlyBeaconBlock) (state.BeaconState, error) {
    32→	if b.Version() < version.Capella {
    33→		return st, nil
    34→	}
    35→	changes, err := b.Body().BLSToExecutionChanges()
    36→	if err != nil {
    37→		return nil, errors.Wrap(err, "could not get BLSToExecutionChanges")
    38→	}
    39→	// Return early if no changes
    40→	if len(changes) == 0 {
    41→		return st, nil
    42→	}
    43→	for _, change := range changes {
    44→		st, err = processBLSToExecutionChange(st, change)
    45→		if err != nil {
    46→			return nil, errors.Wrap(err, "could not process BLSToExecutionChange")
    47→		}
    48→	}
    49→	return st, nil
    50→}
