   115→// ByteSliceRoot is a helper func to merkleize an arbitrary List[Byte, N]
   116→// this func runs Chunkify + MerkleizeVector
   117→// max length is dividable by 32 ( root length )
   118→func ByteSliceRoot(slice []byte, maxLength uint64) ([32]byte, error) {
   119→	chunkedRoots, err := PackByChunk([][]byte{slice})
   120→	if err != nil {
   121→		return [32]byte{}, err
   122→	}
   123→	maxRootLength := (maxLength + 31) / 32 // nearest number divisible by root length (32)
   124→	bytesRoot, err := BitwiseMerkleize(chunkedRoots, uint64(len(chunkedRoots)), maxRootLength)
   125→	if err != nil {
   126→		return [32]byte{}, errors.Wrap(err, "could not compute merkleization")
   127→	}
   128→	bytesRootBuf := new(bytes.Buffer)
   129→	if err := binary.Write(bytesRootBuf, binary.LittleEndian, uint64(len(slice))); err != nil {
   130→		return [32]byte{}, errors.Wrap(err, "could not marshal length")
   131→	}
   132→	bytesRootBufRoot := make([]byte, 32)
   133→	copy(bytesRootBufRoot, bytesRootBuf.Bytes())
   134→	return MixInLength(bytesRoot, bytesRootBufRoot), nil
   135→}
