   235→// SendDeposit sends a single deposit. A record of this deposit will be tracked for the life of the Depositor,
   236→// allowing evaluators to use the deposit history to make assertions about those deposits.
   237→func (d *Depositor) SendDeposit(dep *eth.Deposit, txo *bind.TransactOpts, batch types.DepositBatch) error {
   238→	contract, err := d.contractDepositor()
   239→	if err != nil {
   240→		return err
   241→	}
   242→	txo.Value = amtInGwei(dep)
   243→	root, err := dep.Data.HashTreeRoot()
   244→	if err != nil {
   245→		return err
   246→	}
   247→	sent := time.Now()
   248→	tx, err := contract.Deposit(txo, dep.Data.PublicKey, dep.Data.WithdrawalCredentials, dep.Data.Signature, root)
   249→	if err != nil {
   250→		return errors.Wrap(err, "unable to send transaction to contract")
   251→	}
   252→	d.History().record(&SentDeposit{deposit: dep, time: sent, tx: tx, root: root, batch: batch})
   253→	txo.Nonce = txo.Nonce.Add(txo.Nonce, big.NewInt(1))
   254→	return nil
   255→}
