   257→// txops is a little helper method that creates a TransactOpts (type encapsulating auth/meta data needed to make a tx).
   258→func (d *Depositor) txops(ctx context.Context) (*bind.TransactOpts, error) {
   259→	txo, err := bind.NewKeyedTransactorWithChainID(d.Key.PrivateKey, d.NetworkId)
   260→	if err != nil {
