   263→	txo.Context = ctx
   264→	txo.GasLimit = e2e.DepositGasLimit
   265→	nonce, err := d.Client.PendingNonceAt(ctx, txo.From)
   266→	if err != nil {
   267→		return nil, err
   268→	}
   269→	txo.Nonce = big.NewInt(0).SetUint64(nonce)

