    31→
    32→// WaitForBlocks waits for a certain amount of blocks to be mined by the ETH1 chain before returning.
    33→func WaitForBlocks(web3 *ethclient.Client, key *keystore.Key, blocksToWait uint64) error {
    34→	nonce, err := web3.PendingNonceAt(context.Background(), key.Address)
    35→	if err != nil {
    36→		return err
    37→	}
    38→	chainID, err := web3.NetworkID(context.Background())
    39→	if err != nil {
    40→		return err
    41→	}
    42→	block, err := web3.BlockByNumber(context.Background(), nil)
    43→	if err != nil {
    44→		return err
    45→	}
    46→	finishBlock := block.NumberU64() + blocksToWait
    47→
    48→	for block.NumberU64() <= finishBlock {
    49→		gasPrice, err := web3.SuggestGasPrice(context.Background())
    50→		if err != nil {
    51→			return err
    52→		}
    53→		spamTX := types.NewTransaction(nonce, key.Address, big.NewInt(0), params.SpamTxGasLimit, gasPrice, []byte{})
    54→		signed, err := types.SignTx(spamTX, types.NewEIP155Signer(chainID), key.PrivateKey)
    55→		if err != nil {
    56→			return err
    57→		}
    58→		if err = web3.SendTransaction(context.Background(), signed); err != nil {
    59→			return err
    60→		}
    61→		nonce++
    62→		time.Sleep(timeGapPerMiningTX)
    63→		block, err = web3.BlockByNumber(context.Background(), nil)
    64→		if err != nil {
    65→			return err
    66→		}
    67→	}
    68→	return nil
    69→}
